INSERT INTO content_items (content_id, title, description, image_url, keywords, order_index) VALUES
(4,'Họ hàng','Hai tay khép, lòng bàn tay úp, đầu ngón tay hướng về phía trước, đặt song song trước ngực, giữ nguyên tay trái, di chuyển tay phải xuống dưới 3 bậc.','/images/pages/page_0103.png','họ hàng,gia đình',25),
(4,'Con trai','1. Tay phải khép, khum lại, đặt trước bụng, lòng bàn tay hướng vào trong, đặt chạm các đầu ngón tay vào bụng, đưa tay xuống dưới và lắc nhẹ cổ tay ra ngoài. 2. Tay phải khép, hơi khum lại, lòng bàn tay hướng vào trong, đặt chạm các đầu ngón tay vào cằm.','/images/pages/page_0105.png','con trai,gia đình',26),
(4,'Con gái','1. Tay phải khép, khum lại, đặt trước bụng, lòng bàn tay hướng vào trong, đặt chạm các đầu ngón tay vào bụng, đưa tay xuống dưới và lắc nhẹ cổ tay ra ngoài. 2. Tay phải nắm, ngón cái và ngón trỏ mở ra, nắm nhẹ vào tai (vị trí đeo khuyên tai).','/images/pages/page_0105.png','con gái,gia đình',27),
(4,'Vợ','1. Tay phải nắm, ngón cái và ngón trỏ mở ra, nắm nhẹ vào tai (vị trí đeo khuyên tai). 2. Tay trái khép, hơi khum lại, lòng bàn tay ngửa, đầu ngón tay hướng sang phải, đặt trước ngực. Tay phải khép, lòng bàn tay úp, đầu ngón tay hướng về phía trước, đưa tay phải nắm chặt lấy bàn tay trái.','/images/pages/page_0105.png','vợ,gia đình',28),
(4,'Chồng','1. Tay phải khép, hơi khum lại, lòng bàn tay hướng vào trong, đặt chạm các đầu ngón tay vào cằm. 2. Tay trái khép, hơi khum lại, lòng bàn tay ngửa, đầu ngón tay hướng sang phải, đặt trước ngực. Tay phải khép, lòng bàn tay úp, đầu ngón tay hướng về phía trước, đưa tay phải nắm chặt lấy bàn tay trái.','/images/pages/page_0105.png','chồng,gia đình',29),
(4,'Anh em ruột','1. Hai tay khép, lòng bàn tay úp, đầu ngón tay hướng về phía trước, đặt trước ngực, tay phải đặt dưới tay trái, di chuyển tay phải xuống dưới. 2. Tay phải giống số 1, lòng bàn tay hướng vào trong, đặt chạm đầu ngón trỏ vào phần bụng phải dưới, xoay cổ tay một vòng (theo chiều kim đồng hồ).','/images/pages/page_0106.png','anh em ruột,gia đình',30),
(4,'Chị gái','1. Tay phải nắm, ngón cái và ngón trỏ mở ra, nắm nhẹ vào tai (vị trí đeo khuyên tai). 2. Tay phải nắm, ngón cái mở ra hướng thẳng lên trên, lòng bàn tay hướng vào trong, đặt trước ngực, đưa tay lên trên.','/images/pages/page_0106.png','chị gái,gia đình',31),
(4,'Em út','1. Tay phải khép, lòng bàn tay úp, đầu ngón tay hướng sang trái, đặt áp vào giữa ngực. 2. Tay phải giống chữ I, lòng bàn tay ngửa, đầu ngón tay hướng lên trên, đặt trước ngực, đưa tay xuống dưới.','/images/pages/page_0106.png','em út,gia đình',32),
(4,'Em dâu','1+2. Tay phải khép, lòng bàn tay úp, đầu ngón tay hướng sang trái, đặt áp vào giữa ngực, đưa nhẹ tay lên trên, ra trước đồng thời thay đổi tay giống chữ D.','/images/pages/page_0107.png','em dâu,gia đình',33),
(4,'Anh rể','1+2. Tay phải giống chữ U, lòng bàn tay hướng vào trong, đầu ngón tay hướng lên trên, đặt chạm đầu ngón tay vào cằm, đưa tay xuống dưới - ra trước đồng thời thay đổi tay giống chữ R.','/images/pages/page_0107.png','anh rể,gia đình',34),
(4,'Chị dâu','1+2. Tay phải nắm, ngón cái và ngón trỏ mở ra, nắm nhẹ vào tai (vị trí đeo khuyên tai), đưa tay về phía trước đồng thời thay đổi tay giống chữ D.','/images/pages/page_0107.png','chị dâu,gia đình',35),
(4,'Cháu','Tay phải giống chữ C, lòng bàn tay hướng sang trái, đầu ngón tay hướng lên trên, đặt chạm vào giữa ngực, lắc cổ tay, chuyển các đầu ngón tay hướng xuống dưới.','/images/pages/page_0107.png','cháu,gia đình',36),
(4,'Cháu nội','1. Tay phải giống chữ C, lòng bàn tay hướng sang trái, đầu ngón tay hướng lên trên, đặt chạm vào giữa ngực, lắc cổ tay, chuyển các đầu ngón tay hướng xuống dưới. 2. Tay phải giống chữ N, đặt trước ngực, đưa tay xuống dưới.','/images/pages/page_0108.png','cháu nội,gia đình',37),
(4,'Cháu ngoại','1. Tay phải giống chữ C, lòng bàn tay hướng sang trái, đầu ngón tay hướng lên trên, đặt chạm vào giữa ngực, lắc cổ tay, chuyển các đầu ngón tay hướng xuống dưới. 2. Tay phải giống chữ N, đặt bên phải, ngang tầm ngực, đưa tay về trước.','/images/pages/page_0108.png','cháu ngoại,gia đình',38),
(4,'Bác trai','1. Tay phải giống chữ B, đặt bên phải, ngang tầm với ngực. 2. Tay phải giống chữ N, lòng bàn tay hướng vào trong, đặt chạm hai đầu ngón tay vào cằm.','/images/pages/page_0108.png','bác trai,gia đình',39),
(4,'Bác gái','1. Tay phải nắm, ngón cái và ngón trỏ mở ra, nắm nhẹ vào tai (vị trí đeo khuyên tai). 2. Tay phải giống chữ B, đặt bên phải, ngang tầm với ngực.','/images/pages/page_0108.png','bác gái,gia đình',40),
(4,'Chú','Tay phải giống chữ N, lòng bàn tay hướng vào trong, đầu ngón tay hướng lên trên, đặt chạm đầu ngón tay vào cằm.','/images/pages/page_0109.png','chú,gia đình',41),
(4,'Cậu','Tay phải giống chữ C, lòng bàn tay hướng sang trái, đặt chạm các đầu ngón tay vào cằm.','/images/pages/page_0109.png','cậu,gia đình',42),
(4,'Dì','Tay phải nắm, ngón cái và ngón trỏ mở ra, nắm nhẹ vào tai (vị trí đeo khuyên tai). Sau đó đưa nhẹ tay sang bên phải, chuyển tay giống chữ D.','/images/pages/page_0109.png','dì,gia đình',43),
(4,'Yêu','Tay phải giống chữ Y, lòng bàn tay hướng vào trong, đầu ngón tay hướng sang trái, đặt áp vào ngực trái.','/images/pages/page_0109.png','yêu,tình cảm',44),
(4,'Chăm bẵm','1. Tay phải giống chữ V, lòng bàn tay úp, đầu ngón tay hướng về phía trước, đặt trước cổ, đưa tay về trước. 2. Hai tay khép, lòng bàn tay hướng vào nhau, đầu ngón tay hướng về hai phía, đặt trước ngực, tay phải đặt trên tay trái, giữ nguyên tay trái, di chuyển tay phải lên - xuống (2 lần).','/images/pages/page_0110.png','chăm bẵm,gia đình',45),
(4,'Đùm bọc','1+2. Hai tay mở xoè, lòng bàn tay hướng vào nhau, đầu ngón tay hướng về phía trước, đặt ở hai bên, ngang tầm ngực, đưa đồng thời cả hai tay về giữa ngực, tay phải nằm trên mu bàn tay trái, lòng bàn tay úp.','/images/pages/page_0110.png','đùm bọc,gia đình',46),
(4,'Đồng hồ','Tay trái khép, lòng bàn tay hướng xuống dưới, đầu ngón tay hướng sang phải, đặt trước ngực. Tay phải mở, ngón trỏ và ngón cái tạo thành vòng tròn giống chữ O, đặt vào vị trí đeo đồng hồ ở tay trái.','/images/pages/page_0110.png','đồng hồ,đồ vật',47),
(4,'Điện thoại','Tay phải giống chữ Y, lòng bàn tay hướng sang trái, đầu ngón tay hướng lên trên, đặt áp vào tai phải.','/images/pages/page_0110.png','điện thoại,đồ vật',48),
(4,'Ti vi','Hai tay xoè, lòng bàn tay hướng vào trong, đầu ngón tay hướng sang hai bên, đặt gần nhau, trước ngực, đưa lần lượt hai tay lên, xuống ngược nhau (2 lần).','/images/pages/page_0111.png','ti vi,đồ vật',49),
(4,'Máy vi tính','1. Hai tay giống số 1, lòng bàn tay hướng về phía trước, đầu ngón tay hướng lên trên, đặt gần nhau, trước ngực, đồng thời cả hai tay vẽ một hình chữ nhật. 2. Hai tay xoè, khum lại, lòng bàn tay úp, đầu ngón tay hướng về phía trước, đặt song song trước ngực, cử động các ngón tay của hai tay lên xuống.','/images/pages/page_0111.png','máy vi tính,đồ vật',50),
(4,'Đài','1. Tay phải mở, hơi khum lại, lòng bàn tay hướng ra ngoài, đặt ngang tai phải, xoay cổ tay (2 lần). 2. Các ngón tay phải chụm lại sát nhau, đặt trước ngực, di chuyển đầu ngón tay nửa vòng tròn, rồi xoay ngược lại.','/images/pages/page_0111.png','đài,đồ vật',51),
(4,'Đèn điện','Các ngón tay phải chụm lại, lòng bàn tay hướng xuống dưới, đặt ngang tầm vai, giữ nguyên cánh tay, mở xoè tay ra (lặp lại 2 lần).','/images/pages/page_0111.png','đèn điện,đồ vật',52),
(4,'Quạt','Tay trái khép, lòng bàn tay ngửa, đầu ngón tay hướng sang trái, đặt ngang bụng. Tay phải hơi khum lại, lòng bàn tay hướng về phía trước, đặt chạm khuỷu tay lên lòng bàn tay trái, xoay cổ tay sang hai bên (2 lần).','/images/pages/page_0112.png','quạt,đồ vật',53),
(4,'Tủ lạnh','1. Hai tay giống số 1, đặt chạm hai đầu ngón tay vào nhau, trước trán, đưa đồng thời cả hai tay về một hình chữ nhật đứng. 2. Tay trái khép, lòng bàn tay hướng lên trên, đầu ngón tay hướng sang phải, đặt trước ngực. Tay phải khép, lòng bàn tay hướng sang trái, đầu ngón tay hướng về phía trước, đặt bên trên tay trái, đưa tay mạnh xuống chạm vào giữa lòng bàn tay trái (2 lần).','/images/pages/page_0112.png','tủ lạnh,đồ vật',54),
(4,'Giường','1. Hai tay khép, lòng bàn tay hướng xuống dưới, đầu ngón tay hướng về phía trước, đặt song song trước ngực, đưa đồng thời hai tay sang hai bên. 2. Tay phải khép, đặt áp vào má phải.','/images/pages/page_0112.png','giường,đồ vật',55),
(4,'Chiếu','1. Hai tay chụm, lòng bàn tay hướng xuống dưới, đầu ngón tay hướng xuống dưới, đặt song song trước ngực, đưa đồng thời hai tay ra ngoài rồi lại vào trong. 2. Hai tay khép, lòng bàn tay hướng xuống dưới, đầu ngón tay hướng về phía trước, đặt song song trước ngực, đưa đồng thời hai tay sang hai bên.','/images/pages/page_0112.png','chiếu,đồ vật',56),
(4,'Chăn','Hai tay khép, hơi khum lại, lòng bàn tay hướng vào trong, đầu ngón tay hướng lên trên, đặt song song trước ngực, đưa đồng thời hai tay lên trên úp vào hai vai.','/images/pages/page_0113.png','chăn,đồ vật',57),
(4,'Gối','1. Tay phải giống chữ C, lòng bàn tay hướng về phía trước, đặt trước ngực, đưa tay sang phải. 2. Tay phải khép, đặt áp vào má phải, đầu hơi nghiêng về bên phải.','/images/pages/page_0113.png','gối,đồ vật',58),
(4,'Nồi cơm điện','Hai tay giống chữ S, lòng bàn tay hướng vào nhau, đặt lệch nhau trước ngực, đưa tay phải lên trên và sang phải.','/images/pages/page_0113.png','nồi cơm điện,đồ vật',59),
(4,'Nồi','1. Hai tay giống số 1, lòng bàn tay úp, đặt chạm hai đầu ngón tay vào nhau, trước ngực, đồng thời hai tay vẽ 1 vòng tròn. 2. Hai tay chụm, lòng bàn tay ngửa, đầu ngón tay hướng sang hai bên, đặt ở hai bên, trước ngực, đưa đồng thời hai tay lên trên.','/images/pages/page_0113.png','nồi,đồ vật',60),
(4,'Chảo','1. Hai tay giống số 1, lòng bàn tay úp, đặt chạm hai đầu ngón tay vào nhau, trước ngực, đồng thời hai tay vẽ 1 vòng tròn. 2. Tay phải khép, lòng bàn tay úp, đầu ngón tay hướng về phía trước, lật cổ tay, ngửa bàn tay lên trên.','/images/pages/page_0114.png','chảo,đồ vật',61),
(4,'Dao','Hai tay giống số 1, lòng bàn tay úp, đặt vuông góc ngón trỏ tay phải lên ngón trỏ tay trái ở trước ngực, đưa ngón trỏ tay phải tiến lên, lùi xuống (2 lần).','/images/pages/page_0114.png','dao,đồ vật',62),
(4,'Bát','Tay phải mở, hơi khum lại, lòng bàn tay ngửa, đầu ngón tay hướng lên trên, đặt trước ngực bên phải.','/images/pages/page_0114.png','bát,đồ vật',63),
(4,'Đĩa','Tay trái khép, lòng bàn tay ngửa, đầu ngón tay chếch sang trái, đặt trước ngực. Tay phải giống số 1, lòng bàn tay úp, đầu ngón tay hướng xuống dưới, đưa ngón trỏ theo hình vòng tròn theo chiều kim đồng hồ trên lòng bàn tay trái.','/images/pages/page_0114.png','đĩa,đồ vật',64),
(4,'Thìa','Tay trái khum lại, lòng bàn tay ngửa, đầu ngón tay hướng sang phải, đặt trước ngực. Tay phải giống chữ X, lòng bàn tay hướng vào trong, đặt chạm vào lòng bàn tay trái và di chuyển lên phía cổ tay trái (2 lần).','/images/pages/page_0115.png','thìa,đồ vật',65),
(4,'Đũa','Tay phải giống chữ V, lòng bàn tay hướng vào trong, đầu ngón tay hướng sang trái, hất cổ tay lên, xuống (2 lần).','/images/pages/page_0115.png','đũa,đồ vật',66),
(4,'Phích','Tay trái giống chữ A, lòng bàn tay hướng vào trong, đặt trước ngực. Tay phải khép, lòng bàn tay úp, đầu ngón tay hướng về trước, đặt phía trên tay trái, đưa tay xuống dưới.','/images/pages/page_0115.png','phích,đồ vật',67),
(4,'Ấm','Tay trái khép, lòng bàn tay ngửa, đặt ngang trước ngực. Tay phải giống chữ S, lòng bàn tay hướng sang trái, đầu ngón tay cái hướng lên trên, xoay đầu ngón cái hướng xuống dưới.','/images/pages/page_0115.png','ấm,đồ vật',68),
(4,'Xô','1. Hai tay giống chữ L, lòng bàn tay úp, đặt song song trước ngực, đưa đồng thời cả hai tay chéo xuống dưới - vào giữa. 2. Tay phải nắm, lòng bàn tay hướng vào trong, đặt trước bụng, đưa tay lên trên.','/images/pages/page_0116.png','xô,đồ vật',69),
(4,'Chậu','Hai tay khép, hơi khum lại, lòng bàn tay ngửa, đầu ngón tay hướng về phía trước, đặt song song trước bụng, đưa đồng thời hai tay ngang sang bên tạo thành góc vuông rồi đưa lên trên, lòng bàn tay hướng vào nhau.','/images/pages/page_0116.png','chậu,đồ vật',70),
(4,'Chổi','Tay trái nắm vào khuỷu tay phải. Tay phải khép, lòng bàn tay hướng sang trái, đầu ngón tay hướng xuống dưới, đưa tay sang phải - sang trái (2 lần).','/images/pages/page_0116.png','chổi,đồ vật',71),
(4,'Cây lau nhà','Hai tay nắm, lòng bàn tay hướng vào nhau, đặt trước ngực, tay trái đặt trước, tay phải đặt sau, đưa đồng thời cả hai tay về phía trước (2 lần).','/images/pages/page_0116.png','cây lau nhà,đồ vật',72);
